{
  "name": "TCP 端口映射客户端",
  "name_en": "TCP Port Mapper Client",
  "manufacturer": "",
  "description": "这是一个非物理的软件组件，用于基于 TCP 的 RPC 端口映射通信。在实验系统中，它负责封装与解析 RPC/XDR 报文、查询或注册服务端口，并协助客户端通过端口映射器定位网络服务，而不是直接控制某台实验仪器。",
  "description_en": "This is a non-physical software component for TCP-based RPC port-mapper communication. In lab systems, it packs and unpacks RPC/XDR messages, queries or registers service ports, and helps clients locate network services through a port mapper rather than directly controlling a physical instrument.",
  "tag_hints": [
    "ONC RPC",
    "port mapper",
    "TCP client",
    "XDR serialization",
    "network service discovery",
    "RPC message packing",
    "lab software component"
  ],
  "actions": [
    {
      "action_name": "auto-pack_auth",
      "description": "打包 RPC 认证信息",
      "description_en": "Pack RPC authentication data"
    },
    {
      "action_name": "auto-pack_auth_unix",
      "description": "打包 UNIX 风格的 RPC 认证信息",
      "description_en": "Pack UNIX-style RPC authentication data"
    },
    {
      "action_name": "auto-pack_callheader",
      "description": "打包 RPC 调用头",
      "description_en": "Pack an RPC call header"
    },
    {
      "action_name": "auto-pack_replyheader",
      "description": "打包 RPC 回复头",
      "description_en": "Pack an RPC reply header"
    },
    {
      "action_name": "auto-unpack_auth",
      "description": "解析 RPC 认证信息",
      "description_en": "Unpack RPC authentication data"
    },
    {
      "action_name": "auto-unpack_callheader",
      "description": "解析 RPC 调用头",
      "description_en": "Unpack an RPC call header"
    },
    {
      "action_name": "auto-unpack_replyheader",
      "description": "解析 RPC 回复头",
      "description_en": "Unpack an RPC reply header"
    },
    {
      "action_name": "auto-make_call",
      "description": "构建并执行一次 RPC 调用",
      "description_en": "Build and execute an RPC call"
    },
    {
      "action_name": "auto-start_call",
      "description": "开始构建一次 RPC 调用",
      "description_en": "Start building an RPC call"
    },
    {
      "action_name": "auto-do_call",
      "description": "执行 RPC 调用传输与处理",
      "description_en": "Perform RPC call transport and processing"
    },
    {
      "action_name": "auto-mkcred",
      "description": "生成 RPC 凭据",
      "description_en": "Create RPC credentials"
    },
    {
      "action_name": "auto-mkverf",
      "description": "生成 RPC 校验信息",
      "description_en": "Create RPC verifier data"
    },
    {
      "action_name": "auto-call_0",
      "description": "执行 0 号 RPC 过程调用",
      "description_en": "Call RPC procedure 0"
    },
    {
      "action_name": "auto-set_reply_handler",
      "description": "设置 RPC 回复处理器",
      "description_en": "Set the RPC reply handler"
    },
    {
      "action_name": "auto-set_timeout",
      "description": "设置通信超时时间",
      "description_en": "Set the communication timeout"
    },
    {
      "action_name": "auto-pack_mapping",
      "description": "打包端口映射条目",
      "description_en": "Pack a port-mapping entry"
    },
    {
      "action_name": "auto-pack_pmaplist",
      "description": "打包端口映射列表",
      "description_en": "Pack a port-mapper list"
    },
    {
      "action_name": "auto-pack_call_args",
      "description": "打包远程调用参数",
      "description_en": "Pack remote call arguments"
    },
    {
      "action_name": "auto-unpack_mapping",
      "description": "解析端口映射条目",
      "description_en": "Unpack a port-mapping entry"
    },
    {
      "action_name": "auto-unpack_pmaplist",
      "description": "解析端口映射列表",
      "description_en": "Unpack a port-mapper list"
    },
    {
      "action_name": "auto-unpack_call_result",
      "description": "解析远程调用结果",
      "description_en": "Unpack a remote call result"
    },
    {
      "action_name": "auto-set",
      "description": "注册端口映射",
      "description_en": "Register a port mapping"
    },
    {
      "action_name": "auto-unset",
      "description": "取消端口映射注册",
      "description_en": "Unregister a port mapping"
    },
    {
      "action_name": "auto-get_port",
      "description": "查询服务端口",
      "description_en": "Get a service port"
    },
    {
      "action_name": "auto-dump",
      "description": "导出当前端口映射表",
      "description_en": "Dump the current port-mapping table"
    },
    {
      "action_name": "auto-callit",
      "description": "通过端口映射器转发调用远程过程",
      "description_en": "Invoke a remote procedure through the port mapper"
    },
    {
      "action_name": "auto-my_reply_handler",
      "description": "处理本地定义的 RPC 回复",
      "description_en": "Handle RPC replies with the local reply handler"
    },
    {
      "action_name": "auto-register",
      "description": "注册 RPC 服务",
      "description_en": "Register an RPC service"
    },
    {
      "action_name": "auto-unregister",
      "description": "注销 RPC 服务",
      "description_en": "Unregister an RPC service"
    },
    {
      "action_name": "auto-handle",
      "description": "处理一次传入的 RPC 请求",
      "description_en": "Handle an incoming RPC request"
    },
    {
      "action_name": "auto-turn_around",
      "description": "将请求处理为响应",
      "description_en": "Turn a request into a response"
    },
    {
      "action_name": "auto-handle_0",
      "description": "处理 0 号 RPC 过程请求",
      "description_en": "Handle RPC procedure 0"
    },
    {
      "action_name": "auto-addpackers",
      "description": "添加 RPC 数据打包与解析器",
      "description_en": "Add RPC packers and unpackers"
    },
    {
      "action_name": "auto-loop",
      "description": "运行 RPC 服务循环",
      "description_en": "Run the RPC service loop"
    },
    {
      "action_name": "auto-session",
      "description": "处理一次 RPC 会话",
      "description_en": "Process an RPC session"
    },
    {
      "action_name": "auto-forkingloop",
      "description": "运行支持派生进程的服务循环",
      "description_en": "Run a forking service loop"
    },
    {
      "action_name": "auto-forksession",
      "description": "在派生进程中处理一次会话",
      "description_en": "Process a session in a forked process"
    }
  ]
}

